class Solution {
public:
    int smallestDistancePair(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        auto countPairs = [&](int dist) {
            int count = 0, left = 0;
            for (int right = 0; right < n; right++) {
                while (nums[right] - nums[left] > dist) left++;
                count += right - left;
            }
            return count;
        };
        int low = 0, high = nums[n - 1] - nums[0];
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (countPairs(mid) >= k) high = mid;
            else low = mid + 1;
        }
        return low;
    }
};

class Solution {
    public int smallestDistancePair(int[] nums, int k) {
        Arrays.sort(nums);
        int n = nums.length;
        int low = 0, high = nums[n - 1] - nums[0];
        while (low < high) {
            int mid = low + (high - low) / 2;
            int count = 0, left = 0;
            for (int right = 0; right < n; right++) {
                while (nums[right] - nums[left] > mid) left++;
                count += right - left;
            }
            if (count >= k) high = mid;
            else low = mid + 1;
        }
        return low;
    }
}

var smallestDistancePair = function(nums, k) {
    nums.sort((a, b) => a - b);
    const n = nums.length;
    const countPairs = (dist) => {
        let count = 0, left = 0;
        for (let right = 0; right < n; right++) {
            while (nums[right] - nums[left] > dist) left++;
            count += right - left;
        }
        return count;
    };
    let low = 0, high = nums[n - 1] - nums[0];
    while (low < high) {
        const mid = Math.floor((low + high) / 2);
        if (countPairs(mid) >= k) high = mid;
        else low = mid + 1;
    }
    return low;
};
